/**
 * agent-event-service — write-behind audit log for agent interactions.
 *
 * Every LINE message, LIFF action, and cron job that touches the agent
 * surface writes an event here AFTER the main business logic completes.
 * All writes are best-effort: failures are logged but never block the
 * primary write path.
 */

import type { SupabaseClient } from "@supabase/supabase-js";
import { z } from "zod";

/* ─── Types ─── */

const AGENT_EVENT_KINDS = [
  "text_expense",
  "text_query",
  "text_other",
  "image_rejected",
  "audio_transcribed",
  "needs_group",
  "action_executed",
  "action_failed",
  "task_created",
  "cron_recurring",
  "cron_report",
] as const;

const AGENT_EVENT_STATUSES = [
  "completed",
  "failed",
  "needs_group",
  "rejected",
] as const;

export type AgentEventKind = (typeof AGENT_EVENT_KINDS)[number];
export type AgentEventStatus = (typeof AGENT_EVENT_STATUSES)[number];
export type AgentEventSource = "line" | "liff" | "cron" | "system";

export interface LogAgentEventInput {
  coupleId: number;
  groupId: string | null;
  userId: string;
  source: AgentEventSource;
  sourceEventId: string | null;
  kind: AgentEventKind;
  status: AgentEventStatus;
  inputText: string | null;
  replyText: string | null;
  payload?: Record<string, unknown>;
  pendingActionId?: string;
  taskId?: string;
}

/* ─── Write (best-effort) ─── */

/**
 * Log an agent event. Best-effort: never throws.
 * Call this AFTER the primary business logic has completed.
 */
export async function logAgentEvent(
  db: SupabaseClient,
  input: LogAgentEventInput,
): Promise<void> {
  try {
    await db.from("agent_events").insert({
      couple_id: input.coupleId,
      group_id: input.groupId,
      user_id: input.userId,
      source: input.source,
      source_event_id: input.sourceEventId,
      kind: input.kind,
      status: input.status,
      input_text: input.inputText?.slice(0, 2000) ?? null,
      reply_text: input.replyText?.slice(0, 2000) ?? null,
      payload: input.payload ?? null,
      pending_action_id: input.pendingActionId ?? null,
      task_id: input.taskId ?? null,
      processed_at: new Date().toISOString(),
    });
  } catch (err) {
    console.error("agent_event write failed (non-blocking)", {
      kind: input.kind,
      error: err instanceof Error ? err.message : String(err),
    });
  }
}

/* ─── Read ─── */

const agentEventRowSchema = z.object({
  id: z.string().uuid(),
  couple_id: z.number().int(),
  group_id: z.string().uuid().nullable(),
  user_id: z.string().uuid(),
  source: z.string(),
  source_event_id: z.string().nullable(),
  kind: z.string(),
  status: z.string(),
  input_text: z.string().nullable(),
  reply_text: z.string().nullable(),
  payload: z.record(z.string(), z.unknown()).nullable(),
  pending_action_id: z.string().uuid().nullable(),
  task_id: z.string().uuid().nullable(),
  created_at: z.string(),
  processed_at: z.string().nullable(),
});

export type AgentEventRow = z.infer<typeof agentEventRowSchema>;

export async function getRecentEvents(
  db: SupabaseClient,
  coupleId: number,
  options?: { limit?: number; offset?: number },
): Promise<AgentEventRow[]> {
  const limit = options?.limit ?? 20;
  const offset = options?.offset ?? 0;

  const { data, error } = await db
    .from("agent_events")
    .select("*")
    .eq("couple_id", coupleId)
    .order("created_at", { ascending: false })
    .range(offset, offset + limit - 1);

  if (error) throw new Error(`get recent events failed: ${error.message}`);
  return z.array(agentEventRowSchema).parse(data ?? []);
}

/**
 * ledger-query-read — read-side tool methods.
 *
 * Each function in this file is a plain exported function that
 * previously lived as a `LedgerQueryService` method. The class facade
 * in `ledger-query.ts` re-exposes them as methods without changing
 * the contract.
 */
import type { SupabaseClient } from "@supabase/supabase-js";
import { z } from "zod";
import { loadGroupBalances } from "./balance-loader";
import {
  balanceSummarySchema,
  ledgerVisibleExpenseQuerySchema,
  ledgerVisibleExpenseSchema,
  queryExpensesInputSchema,
  RECENT_SELECT,
  RECURRING_SELECT,
  recentExpensesInputSchema,
  recentExpensesResultSchema,
  recurringItemSchema,
  recurringListResultSchema,
  SELECT_FIELDS,
  summarizeExpenses,
  type BalanceSummary,
  type LedgerVisibleExpense,
  type QueryExpensesInput,
  type QueryExpensesItem,
  type QueryExpensesSummary,
  type RecentExpensesInput,
  type RecentExpensesResult,
  type RecurringListResult,
} from "./ledger-query-core";

/**
 * Run a tool-style query. Returns either an aggregate summary alone
 * (no `limit`) or a summary + items (with `limit`, sorted by
 * `date_desc` or `amount_desc`).
 */
export async function queryExpenses(
  context: { db: SupabaseClient; groupId: string; userId: string },
  rawInput: QueryExpensesInput,
): Promise<
  | { summary: QueryExpensesSummary; items?: QueryExpensesItem[] }
  | { error: string }
> {
  const parsed = queryExpensesInputSchema.parse(rawInput);
  const expenses = await listAccessibleExpenses(context.db, {
    groupId: context.groupId,
    userId: context.userId,
    dateFrom: parsed.dateFrom,
    dateTo: parsed.dateTo,
    tag: parsed.tag,
    member: parsed.member,
    type: parsed.type,
    limitPerLedger: 500,
  });
  const summary = summarizeExpenses(expenses);
  if (!parsed.limit) {
    return { summary };
  }
  const sorted =
    parsed.sort === "amount_desc"
      ? [...expenses].sort((a, b) => b.amount_twd - a.amount_twd)
      : [...expenses].sort((a, b) =>
          b.expense_date.localeCompare(a.expense_date),
        );
  const items = sorted.slice(0, parsed.limit).map((expense) => ({
    id: expense.id,
    description: expense.description,
    merchant: expense.merchant,
    tag: expense.tag,
    amount: expense.amount_twd,
    date: expense.expense_date,
    ledger: expense.ledger,
  }));
  return { summary, items };
}

/**
 * "另一半欠你 NT$…", "你欠另一半 NT$…", or "已結清". Returns
 * `{ error: ... }` on balance lookup failure.
 */
export async function balanceSummary(
  context: { db: SupabaseClient; groupId: string; userId: string },
): Promise<BalanceSummary | { error: string }> {
  let balances: Array<{ userId: string; balanceTwd: number }>;
  try {
    balances = await loadGroupBalances(context.db, context.groupId);
  } catch {
    return { error: "balance lookup failed" };
  }
  const me = balances.find((row) => row.userId === context.userId);
  const partner = balances.find((row) => row.userId !== context.userId);
  const myBalance = me?.balanceTwd ?? 0;
  const partnerBalance = partner?.balanceTwd ?? 0;
  const summary =
    myBalance > 0
      ? `另一半欠你 NT$${myBalance}`
      : myBalance < 0
        ? `你欠另一半 NT$${Math.abs(myBalance)}`
        : "已結清";
  return balanceSummarySchema.parse({
    my_balance: myBalance,
    partner_balance: partnerBalance,
    summary,
  });
}

/**
 * Recent shared + private expenses (de-duped, sorted by created_at
 * desc, mirror rows excluded).
 */
export async function recentExpenses(
  context: { db: SupabaseClient; groupId: string; userId: string },
  rawInput: RecentExpensesInput,
): Promise<RecentExpensesResult> {
  const input = recentExpensesInputSchema.parse(rawInput);
  const queries: Promise<{ data: unknown[] | null; error: unknown }>[] = [];

  if (input.ledger !== "private") {
    queries.push(
      context.db
        .from("expenses")
        .select(RECENT_SELECT)
        .eq("group_id", context.groupId)
        .is("mirror_kind", null)
        .order("created_at", { ascending: false })
        .limit(input.limit) as unknown as Promise<{
        data: unknown[] | null;
        error: unknown;
      }>,
    );
  }

  if (input.ledger !== "shared") {
    queries.push(
      context.db
        .from("expenses")
        .select(RECENT_SELECT)
        .eq("ledger", "private")
        .eq("created_by_user_id", context.userId)
        .is("mirror_kind", null)
        .order("created_at", { ascending: false })
        .limit(input.limit) as unknown as Promise<{
        data: unknown[] | null;
        error: unknown;
      }>,
    );
  }

  const results = await Promise.all(queries);
  const rows = results.flatMap((result) =>
    result.error ? [] : (result.data as Array<Record<string, unknown>>),
  );

  const seen = new Set<string>();
  const unique = rows.filter((row) => {
    const id = String(row.id);
    const deletedAt = row.deleted_at as string | null | undefined;
    if (!id || deletedAt || seen.has(id)) return false;
    seen.add(id);
    return true;
  });

  const sorted = unique
    .sort((a, b) => {
      const left = String(a.created_at ?? "");
      const right = String(b.created_at ?? "");
      if (right === left) return 0;
      return right.localeCompare(left);
    })
    .slice(0, input.limit);

  const items = sorted.map((row) => ({
    id: String(row.id),
    description: String(row.description ?? ""),
    merchant: (row.merchant as string | null) ?? null,
    tag: String(row.tag ?? ""),
    amount_twd: Number(row.amount_twd ?? 0),
    ledger: row.ledger === "private" ? "private" : "shared",
    expense_date: String(row.expense_date ?? ""),
    paid_by:
      String(row.paid_by_user_id ?? "") === context.userId ? "self" : "partner",
    version: Number(row.version ?? 0),
  }));

  return recentExpensesResultSchema.parse({
    count: items.length,
    items,
  });
}

/** Couple-scoped recurring list mapped to the tool contract. */
export async function recurringList(
  context: { db: SupabaseClient; coupleId: number },
): Promise<RecurringListResult | { error: string }> {
  const result = await context.db
    .from("recurring_expenses")
    .select(RECURRING_SELECT)
    .eq("couple_id", context.coupleId)
    .order("next_run_date");
  if (result.error) return { error: "recurring lookup failed" };
  const items = (result.data ?? []).map((row) => ({
    description: String(row.description ?? ""),
    amount: Number(row.amount_twd ?? 0),
    frequency: String(row.frequency ?? ""),
    next_run: String(row.next_run_date ?? ""),
    active: Boolean(row.active),
    tag: String(row.tag ?? ""),
    ledger: row.ledger === "private" ? "private" : "shared",
  }));
  return recurringListResultSchema.parse({ items });
}

/**
 * Shared + private expenses visible to the requesting user, filtered
 * by date / tag / member / type. Mirror rows are excluded. Used by
 * the tool path (query_expenses, recent, search).
 */
export async function listAccessibleExpenses(
  db: SupabaseClient,
  input: z.input<typeof ledgerVisibleExpenseQuerySchema>,
): Promise<LedgerVisibleExpense[]> {
  const query = ledgerVisibleExpenseQuerySchema.parse(input);
  const queries: Promise<{ data: unknown[] | null; error: unknown }>[] = [];

  if (query.type !== "private") {
    let shared = db
      .from("expenses")
      .select(SELECT_FIELDS)
      .eq("group_id", query.groupId)
      .is("deleted_at", null)
      .is("mirror_kind", null);
    if (query.dateFrom) shared = shared.gte("expense_date", query.dateFrom);
    if (query.dateTo) shared = shared.lt("expense_date", query.dateTo);
    if (query.tag) shared = shared.eq("tag", query.tag);
    if (query.member === "me") shared = shared.eq("paid_by_user_id", query.userId);
    else if (query.member === "partner")
      shared = shared.neq("paid_by_user_id", query.userId);
    shared = shared.order("expense_date", { ascending: false }).limit(query.limitPerLedger);
    queries.push(
      shared as unknown as Promise<{ data: unknown[] | null; error: unknown }>,
    );
  }

  if (query.type !== "shared") {
    let privateLedger = db
      .from("expenses")
      .select(SELECT_FIELDS)
      .eq("ledger", "private")
      .eq("created_by_user_id", query.userId)
      .is("deleted_at", null)
      .is("mirror_kind", null);
    if (query.dateFrom) privateLedger = privateLedger.gte("expense_date", query.dateFrom);
    if (query.dateTo) privateLedger = privateLedger.lt("expense_date", query.dateTo);
    if (query.tag) privateLedger = privateLedger.eq("tag", query.tag);
    privateLedger = privateLedger
      .order("expense_date", { ascending: false })
      .limit(query.limitPerLedger);
    queries.push(
      privateLedger as unknown as Promise<{ data: unknown[] | null; error: unknown }>,
    );
  }

  const results = await Promise.all(queries);
  return results.flatMap((result) =>
    result.error ? [] : z.array(ledgerVisibleExpenseSchema).parse(result.data ?? []),
  );
}

/**
 * ledger-query — thin orchestration facade.
 *
 * The actual logic for each read-side method lives in one of:
 *   - `./ledger-query-core`     (row schemas, types, helpers)
 *   - `./ledger-query-read`     (queryExpenses, balanceSummary,
 *                                recentExpenses, recurringList,
 *                                listAccessibleExpenses)
 *   - `./ledger-query-bootstrap` (loadBootstrap)
 *   - `./ledger-query-search`   (searchExpenses, categoryExpenses,
 *                                checkExpenseInSettlements,
 *                                activeGroupId)
 *
 * This file only re-exports the public types / values that callers
 * were already reaching for here, and exposes a `LedgerQueryService`
 * class whose methods are one-line delegations to the modules above.
 *
 * The date helpers `taipeiToday` and `shiftMonth` used to live here
 * too, but they have been removed in favor of the canonical
 * `ledger-shared` versions.
 */
import type { SupabaseClient } from "@supabase/supabase-js";
import { z } from "zod";

import {
  balanceSummary as balanceSummaryImpl,
  listAccessibleExpenses as listAccessibleExpensesImpl,
  queryExpenses as queryExpensesImpl,
  recentExpenses as recentExpensesImpl,
  recurringList as recurringListImpl,
} from "./ledger-query-read";
import { loadBootstrap as loadBootstrapImpl } from "./ledger-query-bootstrap";
import {
  activeGroupId as activeGroupIdImpl,
  categoryExpenses as categoryExpensesImpl,
  checkExpenseInSettlements as checkExpenseInSettlementsImpl,
  searchExpenses as searchExpensesImpl,
} from "./ledger-query-search";

/* -------------------------------------------------------------------------
 * Re-exports of public types and helpers
 *
 * External callers (e.g. `app-server.ts`, `accountant-loaders.ts`,
 * `/api/app/[...path]/route.ts`, `ledger-shared.ts`) have been
 * reaching these from `ledger-query.ts` historically. We keep the
 * path stable so no caller has to change its import.
 * ------------------------------------------------------------------------- */

export {
  ledgerVisibleExpenseSchema,
  ledgerVisibleExpenseQuerySchema,
  type LedgerVisibleExpense,
  type AppUser,
  type AppExpense,
  type QueryExpensesInput,
  type QueryExpensesSummary,
  type QueryExpensesItem,
  type BalanceSummary,
  type RecurringListResult,
  type RecurringItem,
  type RecentExpensesInput,
  type RecentExpensesResult,
  type RecentExpenseItem,
  expensesCsv,
} from "./ledger-query-core";

/* -------------------------------------------------------------------------
 * Service facade
 * ------------------------------------------------------------------------- */

export class LedgerQueryService {
  // ---- Read tools (delegate to ./ledger-query-read) -------------------------
  queryExpenses(
    context: { db: SupabaseClient; groupId: string; userId: string },
    rawInput: Parameters<typeof queryExpensesImpl>[1],
  ) {
    return queryExpensesImpl(context, rawInput);
  }

  balanceSummary(
    context: { db: SupabaseClient; groupId: string; userId: string },
  ) {
    return balanceSummaryImpl(context);
  }

  recentExpenses(
    context: { db: SupabaseClient; groupId: string; userId: string },
    rawInput: Parameters<typeof recentExpensesImpl>[1],
  ) {
    return recentExpensesImpl(context, rawInput);
  }

  recurringList(
    context: { db: SupabaseClient; coupleId: number },
  ) {
    return recurringListImpl(context);
  }

  listAccessibleExpenses(
    db: SupabaseClient,
    input: z.input<
      typeof import("./ledger-query-core").ledgerVisibleExpenseQuerySchema
    >,
  ) {
    return listAccessibleExpensesImpl(db, input);
  }

  // ---- Bootstrap (delegate to ./ledger-query-bootstrap) --------------------
  loadBootstrap(
    context: {
      db: SupabaseClient;
      user: import("./ledger-query-core").AppUser;
    },
  ) {
    return loadBootstrapImpl(context);
  }

  // ---- Search / category / guards (delegate to ./ledger-query-search) -----
  searchExpenses(
    context: { db: SupabaseClient; user: { id: string } },
    searchParams: URLSearchParams,
  ) {
    return searchExpensesImpl(context, searchParams);
  }

  categoryExpenses(
    context: { db: SupabaseClient; user: { id: string } },
    params: URLSearchParams,
  ) {
    return categoryExpensesImpl(context, params);
  }

  checkExpenseInSettlements(
    context: { db: SupabaseClient; user: { couple_id: number } },
    expenseId: string,
  ) {
    return checkExpenseInSettlementsImpl(context, expenseId);
  }
}

import { type SupabaseClient } from "@supabase/supabase-js";
