        amount_twd: command.amountTwd,
        paid_by_user_id: CORE_OWNER,
        expense_date: command.expenseDate,
      },
    };
  };

  const now = new Date().toISOString();
  const activeDraft: any = {
    id: "00000000-0000-4000-8000-000000000071",
    couple_id: 1,
    group_id: GROUP,
    requested_by_user_id: CORE_OWNER,
    draft_type: "expense",
    draft_version: 1,
    payload: {
      type: "expense",
      ledger: "shared",
      paidBy: "self",
      tag: "餐飲",
      description: "晚餐",
    },
    status: "active",
    started_by_event_id: "event-description",
    finished_by_event_id: null,
    amount_twd: null,
    expires_at: new Date(Date.now() + 600_000).toISOString(),
    finished_at: null,
    created_at: now,
    updated_at: now,
  };
  const amountQueries: any[] = [];
  const db: any = {
    from: (table: string) => {
      if (table === "groups") {
        const groupQuery: any = {
          select: () => groupQuery,
          eq: () => groupQuery,
          is: () => groupQuery,
          order: async () => ({
            data: [{ id: GROUP, name: "吃飽喝足" }],
            error: null,
          }),
        };
        return groupQuery;
      }
      const filters = new Map<string, unknown>();
      const query: any = {
        select: () => query,
        eq: (key: string, value: unknown) => {
          filters.set(key, value);
          return query;
        },
        in: () => query,
        gte: () => query,
        order: () => query,
        limit: () => query,
        maybeSingle: async () => {
          amountQueries.push([...filters]);
          return filters.has("finished_by_event_id")
            ? { data: null, error: null }
            : { data: activeDraft, error: null };
        },
      };
      return query;
