    from(table: string) {
      const filters = new Map<string, unknown>();
      const query: any = {
        select: () => query,
        eq: (field: string, value: unknown) => {
          filters.set(field, value);
          return query;
        },
        is: (field: string, value: unknown) => {
          filters.set(field, value);
          return query;
        },
        order: () => query,
        limit: () => query,
