          return { data: null, error: null };
        },
        then: (resolve: (value: { data: unknown; error: null }) => unknown) => {
          if (table === "users") return Promise.resolve(resolve({ data: users, error: null }));
          if (table === "expenses") {
            return Promise.resolve(resolve({
              data: [
