    findings: [],
    suggestions: [],
    source: "fallback",
    created_at: "2026-07-15T00:00:00.000Z",
  };

  const insertedPayloads: Array<Record<string, unknown>> = [];
  const mockDb = {
    from(table: string) {
      if (table === "user_preferences") {
        const query: any = {
          select: () => query,
          eq: () => query,
          single: async () => ({
            data: { active_group_id: GROUP },
            error: null,
          }),
        };
        return query;
      }
      if (table === "expenses") {
        const query: any = {
          select: () => query,
          eq: () => query,
          order: () => query,
          limit: () => Promise.resolve({ data: [], error: null }),
        };
        return query;
      }
      if (table === "accountant_reports") {
        const query: any = {
          insert: (row: Record<string, unknown>) => {
            insertedPayloads.push(row);
            return {
              select: () => ({
                single: async () => ({ data: reportRow, error: null }),
              }),
            };
          },
        };
        return query;
      }
      if (table === "agent_runs") {
        const query: any = {
          insert: () => ({
            select: () => ({
              single: async () => ({ data: { id: "run-1" }, error: null }),
            }),
          }),
        };
        return query;
      }
      throw new Error(`unexpected table ${table}`);
