async function lineNotificationText(
  db: SupabaseClient,
  notification: {
    title: string;
    body: string;
    kind?: string | null;
    group_id?: string | null;
    entity_type?: string | null;
    entity_id?: string | null;
  },
) {
  if (
    notification.kind === "expense" &&
    notification.entity_type === "expense" &&
    z.string().uuid().safeParse(notification.entity_id).success
  ) {
    const [expenseResult, groupResult] = await Promise.all([
      db
        .from("expenses")
        .select("description, amount_twd, expense_date, tag")
        .eq("id", notification.entity_id)
        .single(),
      notification.group_id
        ? db.from("groups").select("name").eq("id", notification.group_id).single()
        : Promise.resolve({ data: null, error: null }),
    ]);
    const expense = z
      .object({
        description: z.string(),
        amount_twd: z.coerce.number().int(),
        expense_date: z.string(),
        tag: z.string(),
      })
      .safeParse(expenseResult.data);
    const group = z
      .object({ name: z.string() })
      .nullable()
      .safeParse(groupResult.data);
    if (!expenseResult.error && expense.success) {
      const groupName = group.success && group.data ? ` ${group.data.name}` : "";
      return `${notification.body}${groupName}\n${expense.data.description} ${notificationMoney(expense.data.amount_twd)}｜${expense.data.expense_date}｜${expense.data.tag}`;
    }
  }
  return notification.title ? `${notification.title}\n${notification.body}` : notification.body;
}

function notificationMoney(amount: number) {
  return `NT$${amount.toLocaleString("en-US")}`;
}

/**
 * pending-action-agent-actions — legacy tool/LINE payload → standard
 * command shape, plus thin `propose*` entry points.
 *
 * These functions own the conversion from a tool-call payload
 * (`{ type, expense, splits, paid_by_user_id, ... }` legacy shape) to
 * a `PendingActionService` standard input. They also build "action
 * previews" that the secretary / AI tools hand to the user before
 * confirmation.
 *
 * They depend on `PendingActionService` only for proposing the
 * resulting action and for the shared balance lookup.
 */
import { z } from "zod";

import { HttpError } from "./http-error";
import { taipeiToday } from "./ledger-shared";
import {
  createSettlementCommandSchema,
  expenseDraftToLegacyPayload,
} from "./ledger-core";
import { loadGroupBalances } from "./balance-loader";
import { loadCoupleUsers, loadExpense } from "./pending-action-loaders";
import { normalizeActionSplits } from "./pending-action-utils";
import type { PendingActionContext } from "./pending-action-types";
import {
  proposeCreateExpenseHelper,
  proposeDeleteExpenseHelper,
  proposeSettlement,
  proposeUpdateExpenseHelper,
} from "./pending-action-proposals";
import type { PendingActionService } from "./pending-action-service";

type ServiceForAgentActions = Pick<
  PendingActionService,
  "execute" | "insert" | "buildStoredPayload"
> & {
  ledgerCommandService: PendingActionService["ledgerCommandService"];
};

type LegacyExpenseInput = {
  ledger: "shared" | "private";
  group_id?: string | null;
  description: string;
  merchant?: string | null;
  notes?: string | null;
  tag?: string;
  amount_twd: number;
  paid_by_user_id: string;
  expense_date: string;
  split_method: "equal" | "exact" | "percentage";
};

type LegacyExpenseUpdates = {
  ledger?: "shared" | "private";
  tag?: string;
  description?: string;
  amount_twd?: number;
  paid_by_user_id?: string;
  expense_date?: string;
};

// ---------------------------------------------------------------------------
// normalize: legacy tool expense shape → standard input shape
// ---------------------------------------------------------------------------
export async function normalizeCreateExpenseInput(
  context: PendingActionContext,
  expenseInput: LegacyExpenseInput,
  splitsInput: unknown,
  groupIdInput: string | null,
) {
  const isPrivate = expenseInput.ledger === "private";
  const groupId = isPrivate ? null : (expenseInput.group_id ?? groupIdInput);

  const splits = normalizeActionSplits(splitsInput);
  let selfValue: number | null = null;
  let partnerValue: number | null = null;
  if (expenseInput.split_method !== "equal" && !isPrivate && splits) {
    const users = await loadCoupleUsers(context);
    const partner = users.find((user) => user.id !== context.user.id);
    selfValue = splits[context.user.id] ?? null;
    partnerValue = partner ? (splits[partner.id] ?? null) : null;
  }

  const paidBy =
    expenseInput.paid_by_user_id === context.user.id
      ? ("self" as const)
      : ("partner" as const);

  return {
    ledger: expenseInput.ledger,
    groupId,
    description: expenseInput.description,
    merchant: expenseInput.merchant ?? null,
    notes: expenseInput.notes ?? null,
    tag: expenseInput.tag ?? "其他",
    amountTwd: expenseInput.amount_twd,
    paidBy,
    expenseDate: expenseInput.expense_date,
    splitMethod: expenseInput.split_method,
    selfValue,
    partnerValue,
  };
}

export async function normalizeUpdateExpenseInput(
  context: PendingActionContext,
  expenseId: string,
  updates: LegacyExpenseUpdates,
  groupIdInput: string | null | undefined,
) {
  const current = await loadExpense(context, expenseId);
  const nextLedger = updates.ledger ?? current.ledger;
  const groupId =
    nextLedger === "private"
      ? null
      : (current.group_id ?? groupIdInput ?? null);
  const amountTwd = updates.amount_twd ?? current.amount_twd;
  const paidByUserId = updates.paid_by_user_id ?? current.paid_by_user_id;

  const selfSplit =
    current.expense_splits.find((split) => split.user_id === context.user.id)
      ?.amount_twd ?? 0;
  const partnerSplit =
    current.expense_splits.find((split) => split.user_id !== context.user.id)
      ?.amount_twd ?? 0;

  let selfValue: number | null = null;
  let partnerValue: number | null = null;
  if (current.split_method !== "equal" && nextLedger !== "private") {
    selfValue =
      current.split_method === "percentage"
        ? Math.round((selfSplit / current.amount_twd) * 10000) / 100
        : selfSplit;
    partnerValue =
      current.split_method === "percentage"
        ? Math.round((partnerSplit / current.amount_twd) * 10000) / 100
        : partnerSplit;
  }

  return {
    standardInput: {
      ledger: nextLedger,
      groupId,
      description: updates.description ?? current.description,
      merchant: current.merchant,
      notes: current.notes,
      tag: updates.tag ?? current.tag,
      amountTwd,
      paidBy:
        paidByUserId === context.user.id
          ? ("self" as const)
          : ("partner" as const),
      expenseDate: updates.expense_date ?? current.expense_date,
      splitMethod: current.split_method,
      selfValue,
      partnerValue,
    },
    current,
  };
}

// ---------------------------------------------------------------------------
// build*: action-preview shapes for the secretary / AI tools
// ---------------------------------------------------------------------------
export async function buildCreateExpenseAction(
  service: ServiceForAgentActions,
  context: PendingActionContext,
  params: {
    ledger: "shared" | "private";
    groupId: string;
    description: string;
    amountTwd: number;
    paidBy: "self" | "partner";
    tag?: string;
    expenseDate?: string;
    merchant?: string | null;
    notes?: string | null;
    splitMethod?: "equal" | "exact" | "percentage";
  },
) {
  if (params.splitMethod === "exact" || params.splitMethod === "percentage") {
    throw new HttpError(400, "AI 記帳目前只支援平均分攤");
  }

  const users = await loadCoupleUsers(context);
  const partner = users.find((u) => u.id !== context.user.id);
  if (params.ledger === "shared" && !partner) {
    throw new HttpError(409, "找不到對方用戶");
  }
  const partnerUserId = partner?.id ?? null;

  const expenseInput = {
    ledger: params.ledger,
    groupId: params.ledger === "private" ? null : params.groupId,
    description: params.description,
    merchant: params.merchant ?? null,
    notes: params.notes ?? null,
    tag: params.tag || "其他",
    amountTwd: params.amountTwd,
    paidBy: params.paidBy,
    expenseDate: params.expenseDate || taipeiToday(),
    splitMethod: "equal" as const,
    selfValue: null,
    partnerValue: null,
  };

  const draft = service.ledgerCommandService.buildExpenseDraft(expenseInput, {
    actorUserId: context.user.id,
    partnerUserId,
  });

  const legacyPayload = expenseDraftToLegacyPayload(draft);
  const { splits, receipt_id, ...expenseFields } = legacyPayload;

  return {
    type: "create_expense" as const,
    groupId: draft.groupId,
    userId: context.user.id,
    expense: expenseFields,
    splits,
  };
}

export async function buildUpdateExpenseAction(
  service: ServiceForAgentActions,
  context: PendingActionContext,
  expenseId: string,
  updates: {
    ledger?: "shared" | "private";
    tag?: string;
    description?: string;
    amountTwd?: number;
    paidBy?: "self" | "partner";
    expenseDate?: string;
  },
) {
  const mapped: LegacyExpenseUpdates = {};
  const ledger = updates.ledger;
  const tag = updates.tag;
  const description = updates.description;
  const amountTwd = updates.amountTwd;
  const expenseDate = updates.expenseDate;
  const paidBy = updates.paidBy;

  if (ledger !== undefined) mapped.ledger = ledger;
  if (tag !== undefined) mapped.tag = tag;
  if (description !== undefined) mapped.description = description;
  if (amountTwd !== undefined) mapped.amount_twd = amountTwd;
  if (expenseDate !== undefined) mapped.expense_date = expenseDate;
  if (paidBy !== undefined) {
    if (paidBy === "self") {
      mapped.paid_by_user_id = context.user.id;
    } else {
      const users = await loadCoupleUsers(context);
      const partner = users.find((u) => u.id !== context.user.id);
      mapped.paid_by_user_id = partner?.id ?? context.user.id;
    }
  }

  const { standardInput, current } = await normalizeUpdateExpenseInput(
    context,
    expenseId,
    mapped,
    undefined,
  );

  const users = await loadCoupleUsers(context);
  const partner = users.find((u) => u.id !== context.user.id);
  const partnerUserId = partner?.id ?? null;

  const draft = service.ledgerCommandService.buildExpenseDraft(standardInput, {
    actorUserId: context.user.id,
    partnerUserId,
  });

  const mappedUpdates: Record<string, unknown> = {};
  if (draft.ledger !== current.ledger) {
    mappedUpdates.ledger = draft.ledger;
  }
  if (draft.tag !== current.tag) {
    mappedUpdates.tag = draft.tag;
  }
  if (draft.description !== current.description) {
    mappedUpdates.description = draft.description;
  }
  if (draft.amountTwd !== current.amount_twd) {
    mappedUpdates.amount_twd = draft.amountTwd;
  }
  if (draft.paidByUserId !== current.paid_by_user_id) {
    mappedUpdates.paid_by_user_id = draft.paidByUserId;
  }
  if (draft.expenseDate !== current.expense_date) {
    mappedUpdates.expense_date = draft.expenseDate;
  }

  if (Object.keys(mappedUpdates).length === 0) {
    throw new HttpError(400, "沒有可修改的欄位");
  }

  return {
    type: "update_expense" as const,
    expenseId,
    expectedVersion: current.version,
    groupId: draft.groupId,
    userId: context.user.id,
    updates: mappedUpdates,
  };
}

export async function buildSettleAction(
  service: ServiceForAgentActions,
  context: PendingActionContext,
  groupId: string,
  amountTwd: number,
) {
  const balances = await loadGroupBalances(context.db, groupId);
  try {
    service.ledgerCommandService.buildSettlementDraft(
      { type: "settle", groupId, amountTwd },
      { balances, actorUserId: context.user.id },
    );
  } catch (error) {
    throw new HttpError(400, error instanceof Error ? error.message : "結清驗證失敗");
  }

  return {
    type: "settle" as const,
    groupId,
    userId: context.user.id,
    amountTwd,
  };
}

// ---------------------------------------------------------------------------
// executeAgentAction — top-level dispatcher for tool / LINE action shape
// ---------------------------------------------------------------------------
export async function executeAgentAction(
  service: ServiceForAgentActions,
  context: PendingActionContext,
  action: Record<string, unknown>,
  metadata?: {
    source?: string;
    sourceEventId?: string;
    idempotencyKey?: string | null;
  },
) {
  const type = typeof action.type === "string" ? action.type : "";
  const source = metadata?.source ?? "line";

  if (type === "create_expense") {
    const expenseInput = z
      .object({
        group_id: z.string().nullable(),
        ledger: z.enum(["shared", "private"]),
        description: z.string().trim().min(1).max(100),
        merchant: z.string().nullable().default(null),
        notes: z.string().nullable().default(null),
        tag: z.string().trim().min(1).max(40),
        amount_twd: z.number().int().positive().max(100_000_000),
        paid_by_user_id: z.string(),
        expense_date: z.iso.date(),
        split_method: z.enum(["equal", "exact", "percentage"]),
      })
      .parse(action.expense);

    const standardInput = await normalizeCreateExpenseInput(
      context,
      expenseInput,
      action.splits,
      action.groupId ? String(action.groupId) : null,
    );

    return proposeCreateExpenseHelper(service, context, standardInput, {
      source,
      sourceEventId: metadata?.sourceEventId,
      idempotencyKey: metadata?.idempotencyKey,
    });
  }

  if (type === "update_expense") {
    const input = z
      .object({
        expenseId: z.string(),
        expectedVersion: z.number().int().positive(),
        groupId: z.string().nullable().optional(),
        updates: z
          .object({
            ledger: z.enum(["shared", "private"]).optional(),
            tag: z.string().trim().min(1).max(40).optional(),
            description: z.string().trim().min(1).max(100).optional(),
            amount_twd: z.number().int().positive().max(100_000_000).optional(),
            paid_by_user_id: z.string().optional(),
            expense_date: z.iso.date().optional(),
          })
          .refine((updates) => Object.keys(updates).length > 0),
      })
      .parse(action);

    const { standardInput } = await normalizeUpdateExpenseInput(
      context,
      input.expenseId,
      input.updates,
      input.groupId,
    );

    return proposeUpdateExpenseHelper(
      service,
      context,
      input.expenseId,
      input.expectedVersion,
      standardInput,
      {
        source,
        sourceEventId: metadata?.sourceEventId,
        idempotencyKey: metadata?.idempotencyKey,
      },
    );
  }

  if (type === "settle") {
    const input = createSettlementCommandSchema.parse({
      type: "settle",
      groupId: action.groupId,
      amountTwd: action.amountTwd,
    });
    return proposeSettlement(
      service,
      context,
      { type: "settle", groupId: input.groupId, amountTwd: input.amountTwd },
      {
        source,
        sourceEventId: metadata?.sourceEventId,
        idempotencyKey: metadata?.idempotencyKey ?? null,
      },
    );
  }

  if (type === "delete_expense") {
    const input = z
      .object({
        expenseId: z.string(),
        expectedVersion: z.number().int().positive(),
      })
      .parse(action);

    return proposeDeleteExpenseHelper(
      service,
      context,
      input.expenseId,
      input.expectedVersion,
      {
        source,
        sourceEventId: metadata?.sourceEventId,
        idempotencyKey: metadata?.idempotencyKey,
      },
    );
  }

  throw new Error(`unsupported agent action: ${type}`);
}

import type { PendingActionService } from "./pending-action-service";
import type { ToolContext } from "./accountant-tools";

let pendingActionServiceInstance: PendingActionService | null = null;

export function registerPendingActionService(service: PendingActionService) {
  pendingActionServiceInstance = service;
}

function getService(): PendingActionService {
  if (!pendingActionServiceInstance) {
    throw new Error("PendingActionService has not been registered");
  }
  return pendingActionServiceInstance;
}

async function getPendingActionContext(ctx: ToolContext) {
  const userResult = await ctx.db
    .from("users")
    .select("id, couple_id, line_user_id, role")
    .eq("id", ctx.userId)
    .single();
  if (userResult.error || !userResult.data) {
    throw new Error("User lookup failed");
  }
  return { db: ctx.db, user: userResult.data };
}

export async function buildCreateExpenseAction(
  ctx: ToolContext,
  params: {
    ledger: "shared" | "private";
    description: string;
    amount_twd: number;
    tag?: string;
    paid_by: "self" | "partner";
    expense_date?: string;
    merchant?: string;
    notes?: string;
    split_method?: "equal" | "exact" | "percentage";
  },
) {
  const service = getService();
  const context = await getPendingActionContext(ctx);
  return service.buildCreateExpenseAction(context, {
    ledger: params.ledger,
    groupId: ctx.groupId,
    description: params.description,
    amountTwd: params.amount_twd,
    paidBy: params.paid_by,
    tag: params.tag,
    expenseDate: params.expense_date,
    merchant: params.merchant,
    notes: params.notes,
    splitMethod: params.split_method,
  });
}

export async function buildUpdateExpenseAction(
  ctx: ToolContext,
  expenseId: string,
  updates: {
    ledger?: "shared" | "private";
    tag?: string;
    description?: string;
    amount_twd?: number;
    paid_by?: "self" | "partner";
    expense_date?: string;
  },
) {
  const service = getService();
  const context = await getPendingActionContext(ctx);
  return service.buildUpdateExpenseAction(context, expenseId, {
    ledger: updates.ledger,
    tag: updates.tag,
    description: updates.description,
    amountTwd: updates.amount_twd,
    paidBy: updates.paid_by,
    expenseDate: updates.expense_date,
  });
}

export async function buildSettleAction(
  ctx: ToolContext,
  amountTwd: number,
) {
  const service = getService();
  const context = await getPendingActionContext(ctx);
  return service.buildSettleAction(context, ctx.groupId, amountTwd);
}

export async function buildDeleteExpenseAction(
  ctx: ToolContext,
  expenseId: string,
) {
  const service = getService();
  const context = await getPendingActionContext(ctx);
  const { data: expense, error } = await ctx.db
    .from("expenses")
    .select("id, version, group_id, deleted_at")
    .eq("id", expenseId)
    .single();
  if (error || !expense) {
    throw new Error("找不到這筆支出");
  }
  if (expense.deleted_at) {
    throw new Error("這筆支出已被刪除");
  }
  return {
    type: "delete_expense" as const,
    expenseId,
    expectedVersion: expense.version,
    userId: context.user.id,
  };
}

/**
 * pending-action.tx.test.ts
 *
 * Executor unit tests for applyPendingActionPlanTx.
 * Uses an inline FakeTxClient + setMockWithTx to test the executor in
 * isolation. This file does NOT touch a real Postgres connection — see
 * pending-action.pg.test.ts for the guarded live test that does.
 */

import assert from "node:assert/strict";
import test from "node:test";
import type { PoolClient } from "pg";
import { setMockWithTx } from "./db/tx";
import { HttpError } from "./http-error";
import {
  createSettlementCommandSchema,
  LedgerCommandService,
  transferCommandSchema,
  voidSettlementCommandSchema,
  type PendingLedgerCommand,
} from "./ledger-core";
import { applyPendingActionPlanTx, TransactionStaleError } from "./pending-action-executor";
import { pendingActionRequestFingerprint } from "./pending-action-idempotency";
import {
  applyLedgerActionTx,
  LedgerActionStaleError,
  lockGroupLedgers,
  type PendingLedgerActionRow,
} from "./pending-action-ledger-tx";
import { PendingActionService } from "./pending-action-service";
import type {
  PendingActionContext,
  PendingActionPlan,
} from "./pending-action-types";

// ---------------------------------------------------------------------------
// Inline FakeTxClient
// ---------------------------------------------------------------------------
type FakeTxCall = { query: string; params?: unknown[] };

class FakeTxClient {
  calls: FakeTxCall[] = [];
  mockResults: Array<{ pattern: string | RegExp; result: unknown }> = [];

  async query(sql: string, params?: unknown[]) {
    const clean = sql.replace(/\s+/g, " ").trim();
    this.calls.push({ query: clean, params });
    for (const item of this.mockResults) {
      if (typeof item.pattern === "string") {
        if (clean.includes(item.pattern)) return item.result;
      } else if (item.pattern.test(clean)) {
        return item.result;
      }
    }
    return { rowCount: 1, rows: [] };
  }
}

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------
const ACTION_ID = "00000000-0000-4000-8000-000000000001";
const USER_ID = "user-owner-001";
const NOW = "2099-01-01T00:00:00.000Z";

function makePendingRow(overrides: Partial<{
  status: string;
  expires_at: string | Date;
  action_type: string;
  request_fingerprint: string | null;
}> = {}) {
  return {
    rowCount: 1,
    rows: [{
      couple_id: 1,
      group_id: null,
      requested_by_user_id: USER_ID,
      status: overrides.status ?? "pending",
      expires_at: overrides.expires_at ?? "2099-12-31T23:59:59.000Z",
      action_type: overrides.action_type ?? "create_expense",
      payload: {},
      request_fingerprint: overrides.request_fingerprint ?? null,
    }],
  };
}

function withFakeTx(fake: FakeTxClient) {
  setMockWithTx(async (cb) => cb(fake as any));
}

// ---------------------------------------------------------------------------
// Tests
// ---------------------------------------------------------------------------

test("tx executor: not_found when row is missing", async () => {
  const fake = new FakeTxClient();
  fake.mockResults.push({ pattern: /FOR UPDATE/i, result: { rowCount: 0, rows: [] } });
  withFakeTx(fake);

  const result = await applyPendingActionPlanTx(fake as any, ACTION_ID, USER_ID, {}, NOW);
  assert.equal(result.result, "not_found");
});

test("tx executor: already_done when status is confirmed", async () => {
  const fake = new FakeTxClient();
  fake.mockResults.push({ pattern: /FOR UPDATE/i, result: makePendingRow({ status: "confirmed" }) });
  withFakeTx(fake);

  const result = await applyPendingActionPlanTx(fake as any, ACTION_ID, USER_ID, {}, NOW);
  assert.equal(result.result, "already_done");
});

test("tx executor: cancelled or expired rows never masquerade as successful", async () => {
  for (const status of ["cancelled", "expired"] as const) {
    const fake = new FakeTxClient();
    fake.mockResults.push({ pattern: /FOR UPDATE/i, result: makePendingRow({ status }) });
    withFakeTx(fake);

    const result = await applyPendingActionPlanTx(
      fake as unknown as PoolClient,
      ACTION_ID,
      USER_ID,
      {},
      NOW,
    );
    assert.equal(result.result, status);
  }
});

test("tx executor: expired when expires_at is past", async () => {
  const fake = new FakeTxClient();
  fake.mockResults.push({
    pattern: /FOR UPDATE/i,
    result: makePendingRow({ expires_at: "2000-01-01T00:00:00.000Z" }),
  });
  withFakeTx(fake);

  const result = await applyPendingActionPlanTx(fake as any, ACTION_ID, USER_ID, {}, NOW);
  assert.equal(result.result, "expired");
  const expiredUpdate = fake.calls.find(c => c.query.includes("expired"));
  assert.ok(expiredUpdate, "should UPDATE to expired");
});

test("tx executor: expires a pg Date value instead of comparing object identity", async () => {
  const fake = new FakeTxClient();
  fake.mockResults.push({
    pattern: /FOR UPDATE/i,
    result: makePendingRow({ expires_at: new Date("2000-01-01T00:00:00.000Z") }),
  });
  withFakeTx(fake);

  const result = await applyPendingActionPlanTx(fake as any, ACTION_ID, USER_ID, {}, NOW);
  assert.equal(result.result, "expired");
});

test("tx executor: confirmed with insert_expenses plan", async () => {
  const fake = new FakeTxClient();
  fake.mockResults.push({
    pattern: /FOR UPDATE/i,
    result: makePendingRow({ action_type: "create_expense" }),
  });
  withFakeTx(fake);

  const plan: PendingActionPlan = {
    insert_expenses: [{
      id: "exp-001",
      couple_id: 1,
      group_id: null,
      ledger: "private",
      description: "晚餐",
      merchant: null,
      notes: null,
      tag: "餐飲",
      amount_twd: 500,
      paid_by_user_id: USER_ID,
      created_by_user_id: USER_ID,
      expense_date: "2026-07-01",
      split_method: "equal",
      source_action_id: ACTION_ID,
    }],
    insert_expense_splits: [{ expense_id: "exp-001", user_id: USER_ID, amount_twd: 500 }],
    insert_activities: [{
      couple_id: 1, group_id: null, actor_user_id: USER_ID,
      entity_type: "expense", entity_id: "exp-001", action: "create",
      before_state: null, after_state: null,
    }],
  };

  const result = await applyPendingActionPlanTx(fake as any, ACTION_ID, USER_ID, plan, NOW);

  assert.equal(result.result, "confirmed");
  assert.equal(result.created_count, 1);
  assert.ok(fake.calls.find(c => c.query.includes("INSERT INTO public.expenses")));
  assert.ok(fake.calls.find(c => c.query.includes("INSERT INTO public.expense_splits")));
  assert.ok(fake.calls.find(c => c.query.includes("INSERT INTO public.activity_events")));
  assert.ok(fake.calls.find(c => c.query.includes("confirmed") && c.query.includes("UPDATE public.pending_actions")));
});

test("tx executor: confirmed with update_expenses plan", async () => {
  const fake = new FakeTxClient();
  fake.mockResults.push({
    pattern: /FOR UPDATE/i,
    result: makePendingRow({ action_type: "update_expense" }),
