test("cancel reports the confirmed state when confirmation wins the CAS race", async () => {
  const service = new PendingActionService();
  let mode: "select" | "update" = "select";
  let selectCalls = 0;
  const db = {
    from(table: string) {
      assert.equal(table, "pending_actions");
      const chain: Record<string, unknown> = {};
      chain.select = () => chain;
      chain.update = () => {
        mode = "update";
        return chain;
      };
      chain.eq = () => chain;
      chain.maybeSingle = async () => {
        if (mode === "update") {
          mode = "select";
          return { data: null, error: null };
        }
        selectCalls += 1;
        if (selectCalls === 1) {
          return {
            data: {
              id: ACTION_ID,
              couple_id: 1,
              group_id: null,
              action_type: "create_expense",
              payload: {},
              status: "pending",
              expires_at: "2099-12-31T23:59:59.000Z",
            },
            error: null,
          };
        }
        return {
          data: { status: "confirmed", action_type: "create_expense" },
          error: null,
        };
      };
      return chain;
    },
  };

  const result = await service.confirm(
    {
      db: db as unknown as PendingActionContext["db"],
      user: {
        id: USER_ID,
        couple_id: 1,
        line_user_id: "line-owner",
        role: "owner",
      },
    },
    ACTION_ID,
    false,
  );

  assert.equal(result.result, "already_done");
});

